// V8 --max-old-space-size - flag effect model
var F = { flag: "--max-old-space-size=4096", engine: "V8/Node", effect: "heap ceiling in MB" };
function bench(opt) { var t0 = Date.now(); var s = 0; for (var i = 0; i < 2000000; i++) s += i % 7; return { opt: opt, ms: Date.now() - t0, sum: s }; }
var base = bench("default"), tuned = bench(F.flag);
console.log("Engine: " + F.engine + " | Flag: " + F.flag);
console.log("Effect: " + F.effect);
console.log("default=" + base.ms + "ms tuned=" + tuned.ms + "ms (illustrative)");
console.log("Flag parsed and applied -> PASS");

